        let r = min(right, other.right), b = min(bottom, other.bottom)
        return r > l && b > t ? Box(l, t, r - l, b - t) : nil
    }

    /// True when `other` lies completely inside this box (edges may touch).
    public func contains(_ other: Box) -> Bool {
        other.x >= x && other.y >= y && other.right <= right && other.bottom <= bottom
    }
}

