/// Derives effects from what changed between two frames, never from the simulation internals:
///  - an entity of an effect kind that disappears while its last box was completely inside the world
///    bursts (particles) or pops (ring, plus "+N" when the score rose in the same frame);
///  - lives going down flashes the world and shakes it briefly.
/// Entities that expire or leave the world by their own motion are never completely inside when they
/// vanish, so they cause no effect. Use effect `.none` for kinds that could still do so.
public struct EffectTracker: Sendable {
    public static let particleSeconds = 0.4
    public static let ringSeconds = 0.3
    public static let popupSeconds = 0.6
    public static let flashSeconds = 0.25
    public static let shakeSeconds = 0.15
    public static let shakeUnits = 12.0
    public static let popupRise = 60.0
    public static let maxParticles = 96
    public static let maxRings = 16
    public static let maxPopups = 8
    private static let d = 0.70710677
    private static let directions: [(Double, Double)] = [
        (1, 0), (d, d), (0, 1), (-d, d), (-1, 0), (-d, -d), (0, -1), (d, -d),
    ]

    private let effects: [Effect]
    private let world: Box
    private var previous: [Tracked] = []
    private var lastScore: Int64?
    private var lastLives: Int64?
    private var shakeAge = EffectTracker.shakeSeconds

    public private(set) var particles: [Particle] = []
    public private(set) var rings: [Ring] = []
    public private(set) var popups: [Popup] = []
    /// 1 right after a life is lost, falling to 0.
    public private(set) var flash = 0.0

    public init(effects: [Effect], world: Box) {
        self.effects = effects
        self.world = world
    }

    /// Call once per rendered frame with the state after the frame's ticks.
    public mutating func observe(score: Int64, lives: Int64, entities: [Tracked]) {
        let nowIds = Set(entities.map(\.id))
        let scoreDelta = lastScore.map { score - $0 } ?? 0
        var popupDone = false
        for gone in previous where !nowIds.contains(gone.id) {
            let effect = gone.kind < effects.count ? effects[gone.kind] : .none
            if effect == .none || !world.contains(gone.box) { continue }
            let cx = gone.box.x + gone.box.w / 2, cy = gone.box.y + gone.box.h / 2
            let reach = max(gone.box.w, gone.box.h)
            if effect == .burst {
                for (dx, dy) in EffectTracker.directions where particles.count < EffectTracker.maxParticles {
                    particles.append(Particle(x: cx, y: cy, vx: dx * reach * 2, vy: dy * reach * 2,
                                              size: max(4, reach * 0.12), kind: gone.kind))
                }
            } else if rings.count < EffectTracker.maxRings {
                rings.append(Ring(x: cx, y: cy, maxRadius: reach, kind: gone.kind))
            }
            if !popupDone && scoreDelta > 0 && popups.count < EffectTracker.maxPopups {
                popups.append(Popup(text: "+\(scoreDelta)", x: cx, y: cy))
                popupDone = true
            }
        }
        if let before = lastLives, lives < before {
            flash = 1
            shakeAge = 0
        }
        previous = entities
        lastScore = score
        lastLives = lives
    }

    /// Moves time forward by the frame time in seconds (display time, not simulation time).
    public mutating func advance(_ dt: Double) {
        if dt <= 0 { return }
        for i in particles.indices {
            particles[i].x += particles[i].vx * dt
            particles[i].y += particles[i].vy * dt
            particles[i].age += dt
        }
        for i in rings.indices { rings[i].age += dt }
        for i in popups.indices {
            popups[i].age += dt
            popups[i].y -= EffectTracker.popupRise * dt
        }
        particles.removeAll { $0.age >= EffectTracker.particleSeconds }
        rings.removeAll { $0.age >= EffectTracker.ringSeconds }
        popups.removeAll { $0.age >= EffectTracker.popupSeconds }
        flash = max(0, flash - dt / EffectTracker.flashSeconds)
        shakeAge += dt
    }

    /// Horizontal shake offset in world units; alternates sign every 1/60 s and fades out.
    public var shakeX: Double {
        if shakeAge >= EffectTracker.shakeSeconds { return 0 }
        let sign = Int(shakeAge * 60) % 2 == 0 ? 1.0 : -1.0
        return EffectTracker.shakeUnits * (1 - shakeAge / EffectTracker.shakeSeconds) * sign
    }

    public var shakeY: Double { shakeX * -0.5 }

    public mutating func reset() {
        previous = []
        lastScore = nil
        lastLives = nil
        particles = []; rings = []; popups = []
        flash = 0
        shakeAge = EffectTracker.shakeSeconds
    }
}

/// HUD, card and glyph texts.
public enum Texts {
    public static let maxLifeGlyphs = 8

    /// One `glyph` per life, "+n" when more than `maxLifeGlyphs`; the empty glyph shows the number as text.
    public static func lives(glyph: String, lives: Int64) -> String {
        let n = max(0, lives)
        if glyph.isEmpty { return "lives \(n)" }
        let shown = Int(min(n, Int64(maxLifeGlyphs)))
        let extra = n > Int64(maxLifeGlyphs) ? " +\(n - Int64(maxLifeGlyphs))" : ""
        return String(repeating: glyph, count: shown) + extra
    }

    public static func score(label: String, score: Int64) -> String { "\(label) \(score)" }

    /// The end card is a win when the game ended with lives left.
    public static func endTitle(lives: Int64, winTitle: String, loseTitle: String) -> String {
        lives > 0 ? winTitle : loseTitle
    }

    /// Edge length of the square a glyph is drawn in: a little smaller than the shorter side of its box.
    public static func glyphSize(_ box: Box) -> Double { min(box.w, box.h) * 0.9 }
}
